import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,e}from"./app-09e0be14.js";const t={},o=e(`<h1 id="ntl-c-数论与多项式计算库" tabindex="-1"><a class="header-anchor" href="#ntl-c-数论与多项式计算库" aria-hidden="true">#</a> ntl（C++ 数论与多项式计算库）</h1><blockquote><p>Homebrew 版本 11.6.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install ntl</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>NTL（Number Theory Library）是一个高性能、可移植的 <strong>C++ 数论与多项式计算库</strong>，由 Victor Shoup 开发维护，为密码学、计算数论、代数与多项式运算提供经过精心优化的任意精度整数、有限域、多项式、矩阵等基础类型与算法。它把&quot;大整数模幂运算、有限域上的多项式算术、最大公因子、素性判定、椭圆曲线算术&quot;等复杂数学操作封装成简洁的 C++ 类，让开发者不必自行实现底层算法。</p><p>典型应用场景：公钥密码学实现（RSA、ElGamal、Paillier 等）、密码学协议原语开发、有限域与多项式运算、计算数论研究、格基约化（LLL 算法）以及教育科研中的算法验证。配合 GMP（GNU Multiple Precision Arithmetic Library）使用可获得更强的性能，其内置的 <code>ZZ</code>（任意精度整数）、<code>ZZ_p</code>（模素数域）、<code>ZZX</code>（整数多项式）等类型被学术与工业界广泛采用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装、升级、卸载，以及验证：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装（会自动拉取依赖的 GMP）</span>
brew <span class="token function">install</span> ntl

<span class="token comment"># 升级到最新版</span>
brew upgrade ntl

<span class="token comment"># 卸载</span>
brew uninstall ntl

<span class="token comment"># 验证安装成功（应输出类似 11.6.0）</span>
brew info ntl

<span class="token comment"># 查看库文件是否已生成（Apple Silicon 路径）</span>
<span class="token function">ls</span> /opt/homebrew/lib/libntl.* /opt/homebrew/include/NTL/*.h

<span class="token comment"># 用 pkg-config 确认版本（NTL 提供 pkg-config 支持）</span>
pkg-config <span class="token parameter variable">--modversion</span> ntl
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>brew info ntl</code> 中显示版本号为 <code>11.6.0</code>、<code>ls</code> 能看到 <code>libntl.dylib</code> / <code>libntl.a</code> 以及 <code>NTL</code> 头文件目录即表示安装成功。若提示 <code>command not found</code>，先确认 <code>/opt/homebrew/bin</code>（Apple Silicon）或 <code>/usr/local/bin</code>（Intel）已在 PATH 中。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>NTL 是<strong>纯 C++ 库</strong>而非命令行程序，因此&quot;命令&quot;体现为 <code>pkg-config</code>/<code>brew</code> 查询、编译链接参数，以及库内最常用类型与函数。下表给出最常见的用法：</p><table><thead><tr><th>命令/类型/函数</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>pkg-config --cflags --libs ntl</code></td><td>输出编译与链接参数</td><td><code>c++ app.cpp $(pkg-config --cflags --libs ntl)</code></td></tr><tr><td><code>brew info ntl</code> / <code>brew --prefix ntl</code></td><td>查询版本与安装路径</td><td><code>brew --prefix ntl</code> 输出目录</td></tr><tr><td><code>ZZ</code></td><td>任意精度（变长）有符号整数</td><td><code>ZZ a = conv&lt;ZZ&gt;(&quot;12345678901234567890&quot;);</code></td></tr><tr><td><code>ZZ_p</code></td><td>模素数 p 的有限域元素</td><td><code>ZZ_p::init(p); ZZ_p x = random_ZZ_p();</code></td></tr><tr><td><code>power_mod(a, e, m)</code></td><td>大整数模幂运算（快速幂）</td><td><code>ZZ r = power_mod(a, e, m);</code></td></tr><tr><td><code>GCD(a, b)</code></td><td>计算最大公因子</td><td><code>ZZ g = GCD(a, b);</code></td></tr><tr><td><code>ProbPrime(n, t)</code></td><td>概率素性判定（Miller–Rabin，t 轮）</td><td><code>bool isp = ProbPrime(n, 20);</code></td></tr><tr><td><code>LLL()</code></td><td>格基约化（LLL 算法）</td><td><code>mat_ZZ B; LLL(B);</code></td></tr><tr><td><code>ZZX</code> / <code>ZZ_pX</code></td><td>整数/有限域上的多项式</td><td><code>ZZX f = conv&lt;ZZX&gt;(...);</code></td></tr><tr><td><code>RandomLen_ZZ(n)</code> / <code>RandomPrime_ZZ(n)</code></td><td>生成 n 位随机整数 / 随机素数</td><td><code>ZZ prime = RandomPrime_ZZ(256);</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><p>NTL 是纯库，以下示例演示如何用 brew 安装后，在 C/C++ 中链接并使用它的核心数论功能。</p><h3 id="示例-1-最小可编译的数论程序-模幂、gcd、素性判定" tabindex="-1"><a class="header-anchor" href="#示例-1-最小可编译的数论程序-模幂、gcd、素性判定" aria-hidden="true">#</a> 示例 1：最小可编译的数论程序（模幂、GCD、素性判定）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 准备源码</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> ntl_demo.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;NTL/ZZ.h&gt;
#include &lt;iostream&gt;

using namespace std;
using namespace NTL;

int main() {
    // 任意精度整数
    ZZ a = conv&lt;ZZ&gt;(&quot;123456789012345678901234567890&quot;);
    ZZ b = conv&lt;ZZ&gt;(&quot;987654321098765432109876543210&quot;);

    cout &lt;&lt; &quot;a = &quot; &lt;&lt; a &lt;&lt; endl
         &lt;&lt; &quot;b = &quot; &lt;&lt; b &lt;&lt; endl;

    // 最大公因子
    cout &lt;&lt; &quot;GCD(a, b) = &quot; &lt;&lt; GCD(a, b) &lt;&lt; endl;

    // 模幂运算：7^100 mod 1000000007
    ZZ p = conv&lt;ZZ&gt;(&quot;1000000007&quot;);
    cout &lt;&lt; &quot;7^100 mod 1000000007 = &quot; &lt;&lt; power_mod(conv&lt;ZZ&gt;(7), conv&lt;ZZ&gt;(100), p) &lt;&lt; endl;

    // 素性判定（Miller–Rabin，20 轮）
    ZZ prime = RandomPrime_ZZ(128);
    cout &lt;&lt; &quot;随机 128 位素数: &quot; &lt;&lt; prime &lt;&lt; endl;
    cout &lt;&lt; &quot;ProbPrime(prime, 20) = &quot; &lt;&lt; ProbPrime(prime, 20) &lt;&lt; endl;
    return 0;
}
EOF</span>

<span class="token comment"># 2. 编译并链接（pkg-config 自动带入 -I 与 -L/-lntl）</span>
c++ ntl_demo.cpp <span class="token parameter variable">-o</span> ntl_demo <span class="token variable"><span class="token variable">$(</span>pkg-config <span class="token parameter variable">--cflags</span> <span class="token parameter variable">--libs</span> ntl<span class="token variable">)</span></span>

<span class="token comment"># 3. 运行</span>
./ntl_demo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出大致为：打印两个大整数、<code>GCD(a, b) = 900000000090000000009</code>、<code>7^100 mod 1000000007 = ...</code>（一个小于模数的整数）、随机生成的 128 位素数及其素性判定 <code>1</code>。</p><h3 id="示例-2-有限域-zz-p-上的运算" tabindex="-1"><a class="header-anchor" href="#示例-2-有限域-zz-p-上的运算" aria-hidden="true">#</a> 示例 2：有限域 <code>ZZ_p</code> 上的运算</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> zzp_demo.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;NTL/ZZ_p.h&gt;
#include &lt;NTL/ZZ.h&gt;
#include &lt;iostream&gt;

using namespace std;
using namespace NTL;

int main() {
    // 初始化模数 p（素数）
    ZZ p = conv&lt;ZZ&gt;(&quot;1000000007&quot;);
    ZZ_p::init(p);

    // 域内元素运算，自动取模
    ZZ_p x = random_ZZ_p();
    ZZ_p y = random_ZZ_p();
    cout &lt;&lt; &quot;x = &quot; &lt;&lt; x &lt;&lt; endl
         &lt;&lt; &quot;y = &quot; &lt;&lt; y &lt;&lt; endl;
    cout &lt;&lt; &quot;x + y = &quot; &lt;&lt; x + y &lt;&lt; endl;
    cout &lt;&lt; &quot;x * y = &quot; &lt;&lt; x * y &lt;&lt; endl;

    // 域内乘法逆元（要求 x 非零）
    if (x != 0) {
        cout &lt;&lt; &quot;x^{-1} = &quot; &lt;&lt; inv(x) &lt;&lt; endl;
        cout &lt;&lt; &quot;x * x^{-1} = &quot; &lt;&lt; x * inv(x) &lt;&lt; endl;
    }
    return 0;
}
EOF</span>

c++ zzp_demo.cpp <span class="token parameter variable">-o</span> zzp_demo <span class="token variable"><span class="token variable">$(</span>pkg-config <span class="token parameter variable">--cflags</span> <span class="token parameter variable">--libs</span> ntl<span class="token variable">)</span></span>
./zzp_demo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出中的 <code>x * y</code>、<code>x + y</code> 均为模 <code>1000000007</code> 后的结果；<code>x * x^{-1} = 1</code>（在域中等于单位元），验证了求逆的正确性。</p><h3 id="示例-3-用-cmake-集成-ntl-配合-gmp" tabindex="-1"><a class="header-anchor" href="#示例-3-用-cmake-集成-ntl-配合-gmp" aria-hidden="true">#</a> 示例 3：用 CMake 集成 NTL（配合 GMP）</h3><p>写一个 <code>CMakeLists.txt</code> 并构建：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> CMakeLists.txt <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
cmake_minimum_required(VERSION 3.10)
project(ntl_demo CXX)
set(CMAKE_CXX_STANDARD 17)

find_package(PkgConfig REQUIRED)
pkg_check_modules(NTL REQUIRED IMPORTED_TARGET ntl)

add_executable(ntl_demo ntl_demo.cpp)
target_link_libraries(ntl_demo PRIVATE PkgConfig::NTL)
EOF</span>

<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> build <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> build
cmake <span class="token punctuation">..</span>
<span class="token function">make</span>
./ntl_demo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-用-pkg-config-简化编译-避免手写路径" tabindex="-1"><a class="header-anchor" href="#_1-用-pkg-config-简化编译-避免手写路径" aria-hidden="true">#</a> 1. 用 pkg-config 简化编译，避免手写路径</h3><p>只要 <code>PKG_CONFIG_PATH</code> 指向 Homebrew 的 <code>lib/pkgconfig</code>，即可用 <code>$(pkg-config --cflags --libs ntl)</code> 自动获得头文件与链接路径，无需手写 <code>-I</code> 与 <code>-L</code>。若在命令行直接编译，等价写法为：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># Apple Silicon</span>
c++ demo.cpp <span class="token parameter variable">-o</span> demo -I/opt/homebrew/include -L/opt/homebrew/lib <span class="token parameter variable">-lntl</span> <span class="token parameter variable">-lgmp</span>
<span class="token comment"># Intel</span>
c++ demo.cpp <span class="token parameter variable">-o</span> demo -I/usr/local/include -L/usr/local/lib <span class="token parameter variable">-lntl</span> <span class="token parameter variable">-lgmp</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若 <code>pkg-config</code> 找不到 <code>ntl</code>，可显式补充 <code>PKG_CONFIG_PATH</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">PKG_CONFIG_PATH</span><span class="token operator">=</span><span class="token string">&quot;/opt/homebrew/lib/pkgconfig:<span class="token variable">\${PKG_CONFIG_PATH}</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_2-配合-gmp-获得更高性能" tabindex="-1"><a class="header-anchor" href="#_2-配合-gmp-获得更高性能" aria-hidden="true">#</a> 2. 配合 GMP 获得更高性能</h3><p>NTL 内部可选用 GMP 作为底层大整数引擎。Homebrew 的 <code>ntl</code> 默认链接 GMP，性能显著优于自带的便携实现。若手动从源码构建并希望显式启用 GMP，可配置 <code>./configure NTL_GMP_LIP=on</code>。检查你的构建是否用了 GMP：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># NTL 头文件中的宏（若为 1 表示启用 GMP 作为 LIP 引擎）</span>
<span class="token function">grep</span> <span class="token parameter variable">-r</span> <span class="token string">&quot;NTL_GMP_LIP&quot;</span> /opt/homebrew/include/NTL/ <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null

<span class="token comment"># 也可以看链接的符号是否来自 libgmp</span>
otool <span class="token parameter variable">-L</span> /opt/homebrew/lib/libntl.dylib <span class="token operator">|</span> <span class="token function">grep</span> gmp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-随机数种子与可复现性" tabindex="-1"><a class="header-anchor" href="#_3-随机数种子与可复现性" aria-hidden="true">#</a> 3. 随机数种子与可复现性</h3><p>NTL 的随机数基于内部伪随机生成器。需要可复现结果时可用 <code>SetSeed</code> 设置种子：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ.h&gt;</span></span>
<span class="token function">SetSeed</span><span class="token punctuation">(</span><span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token number">42</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 之后 random_ZZ_p() 等每次产生相同序列</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>科研与调试场景常用此技巧让实验可重复。生产环境则使用系统熵初始化，避免固定种子。</p><h3 id="_4-用-lll-做格基约化与密码分析" tabindex="-1"><a class="header-anchor" href="#_4-用-lll-做格基约化与密码分析" aria-hidden="true">#</a> 4. 用 LLL 做格基约化与密码分析</h3><p>NTL 提供完整的 <code>LLL</code> 格基约化实现，常用于基于格的密码学（如 NTRU）分析与最邻近平面攻击等研究：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/mat_ZZ.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/LLL.h&gt;</span></span>
mat_ZZ B<span class="token punctuation">;</span>
<span class="token comment">// ... 填充格基向量 ...</span>
<span class="token function">LLL</span><span class="token punctuation">(</span>B<span class="token punctuation">,</span> <span class="token number">0.99</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// delta 参数控制约化质量</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>delta</code> 取值在 <code>0.25</code> 到 <code>1.0</code> 之间，越接近 1 约化越彻底但耗时越高。</p><h3 id="_5-常用多项式运算-zzx-zz-px" tabindex="-1"><a class="header-anchor" href="#_5-常用多项式运算-zzx-zz-px" aria-hidden="true">#</a> 5. 常用多项式运算 <code>ZZX</code> / <code>ZZ_pX</code></h3><p>NTL 的多项式类支持系数级大整数/有限域运算，直接支持加减乘除、求导、求值、因式分解等：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZX.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ_pX.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token keyword">using</span> <span class="token keyword">namespace</span> std<span class="token punctuation">;</span> <span class="token keyword">using</span> <span class="token keyword">namespace</span> NTL<span class="token punctuation">;</span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 整数多项式 f(x) = 3x^2 + 2x + 1</span>
    ZZX f<span class="token punctuation">;</span>
    f<span class="token punctuation">.</span><span class="token function">SetLength</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    f<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> f<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span> f<span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span> <span class="token comment">// f(x) = 3x^2 + 2x + 1</span>

    <span class="token comment">// 求值 f(5) = 3*25 + 2*5 + 1 = 86</span>
    cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;f(5) = &quot;</span> <span class="token operator">&lt;&lt;</span> <span class="token function">eval</span><span class="token punctuation">(</span>f<span class="token punctuation">,</span> <span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">&lt;&lt;</span> endl<span class="token punctuation">;</span>

    <span class="token comment">// 多项式乘法：g(x) = x + 1</span>
    ZZX one<span class="token punctuation">,</span> x<span class="token punctuation">,</span> g<span class="token punctuation">;</span>
    one <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>                  <span class="token comment">// 常数 1</span>
    x<span class="token punctuation">.</span><span class="token function">SetLength</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> x<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token comment">// x</span>
    g <span class="token operator">=</span> one <span class="token operator">+</span> x<span class="token punctuation">;</span>              <span class="token comment">// x + 1</span>
    ZZX prod <span class="token operator">=</span> f <span class="token operator">*</span> g<span class="token punctuation">;</span>         <span class="token comment">// 系数即乘积</span>
    cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;f * (x+1) = &quot;</span> <span class="token operator">&lt;&lt;</span> prod <span class="token operator">&lt;&lt;</span> endl<span class="token punctuation">;</span>
    <span class="token comment">// 求值一致性：f(5) * g(5) = 86 * 6 = 516</span>
    cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;prod(5) = &quot;</span> <span class="token operator">&lt;&lt;</span> <span class="token function">eval</span><span class="token punctuation">(</span>prod<span class="token punctuation">,</span> <span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">&lt;&lt;</span> endl<span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-常用配置项与个性化设置" tabindex="-1"><a class="header-anchor" href="#_6-常用配置项与个性化设置" aria-hidden="true">#</a> 6. 常用配置项与个性化设置</h3><p>NTL 提供若干可在编译时/运行时控制的选项：</p><table><thead><tr><th>配置项</th><th>作用</th><th>说明</th></tr></thead><tbody><tr><td><code>NTL_GMP_LIP</code></td><td>是否用 GMP 做大整数引擎</td><td><code>./configure NTL_GMP_LIP=on</code>（源码构建）</td></tr><tr><td><code>NTL_THREADS</code></td><td>启用/禁用 OpenMP 多线程</td><td>默认开启；离线构建可 <code>=off</code> 减少依赖</td></tr><tr><td><code>NTL_EXCEPTIONS</code></td><td>是否抛出 C++ 异常</td><td><code>on</code> 时错误抛异常，<code>off</code> 时走 <code>Error</code> 回调</td></tr><tr><td><code>NTL_STD_CXX11</code></td><td>是否强制 C++11 及以上标准</td><td>默认自动检测</td></tr><tr><td><code>SetSeed</code></td><td>设定随机种子</td><td>运行时函数，保证可复现</td></tr><tr><td><code>ZZ_p::init(p)</code></td><td>设定模数 p</td><td>运行时函数，影响所有 <code>ZZ_p</code> 运算</td></tr><tr><td><code>LLL(delta)</code></td><td>控制 LLL 约化质量</td><td>运行时参数</td></tr></tbody></table><p>在 CMake 里若希望链接到自定义构建的 NTL（而非 Homebrew 的），可用 <code>pkg_check_modules</code> 指定自定义前缀，或直接 <code>find_library(NTL_LIB ntl PATH ...)</code> + <code>find_path(NTL_INC NTL/ZZ.h PATH ...)</code>。</p><h3 id="_7-编译优化与多线程" tabindex="-1"><a class="header-anchor" href="#_7-编译优化与多线程" aria-hidden="true">#</a> 7. 编译优化与多线程</h3><p>NTL 支持 OpenMP 并行加速（默认开启）。编译时加 <code>-fopenmp</code>，并链接 OpenMP 运行库：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 若 NTL 以 NTL_THREADS=on 构建，编译时启用 OpenMP</span>
c++ <span class="token parameter variable">-O2</span> <span class="token parameter variable">-fopenmp</span> app.cpp <span class="token parameter variable">-o</span> app <span class="token variable"><span class="token variable">$(</span>pkg-config <span class="token parameter variable">--cflags</span> <span class="token parameter variable">--libs</span> ntl<span class="token variable">)</span></span> <span class="token parameter variable">-lgomp</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>-O2</code>/<code>-O3</code> 显著提升大整数运算性能。</li><li>若链接报 <code>library not found for -lgomp</code>，说明编译期未启用 OpenMP，去掉 <code>-fopenmp</code> 与 <code>-lgomp</code> 即可。</li></ul><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-编译时报-fatal-error-ntl-zz-h-file-not-found" tabindex="-1"><a class="header-anchor" href="#_1-编译时报-fatal-error-ntl-zz-h-file-not-found" aria-hidden="true">#</a> 1. 编译时报 &quot;fatal error: &#39;NTL/ZZ.h&#39; file not found&quot;</h3><p>头文件路径未找到。确认编译命令中带上 <code>$(pkg-config --cflags ntl)</code>，或用 <code>brew --prefix ntl</code> 找到安装目录并显式 <code>-I&lt;prefix&gt;/include</code>。Homebrew 的 include 默认在 <code>/opt/homebrew/include</code>。</p><h3 id="_2-链接时报-undefined-symbols-ntl-或-library-not-found-for-lntl" tabindex="-1"><a class="header-anchor" href="#_2-链接时报-undefined-symbols-ntl-或-library-not-found-for-lntl" aria-hidden="true">#</a> 2. 链接时报 &quot;Undefined symbols ... _NTL::...&quot; 或 &quot;library not found for -lntl&quot;</h3><p>链接时遗漏了 <code>-lntl</code> 或库路径。务必在命令末尾加上 <code>$(pkg-config --libs ntl)</code>，或显式写 <code>-L/opt/homebrew/lib -lntl</code>（Intel 机为 <code>/usr/local/lib</code>）。由于 NTL 依赖 GMP，若 GMP 未装或链接顺序错误，可显式追加 <code>-lgmp</code>。</p><h3 id="_3-用-g-gcc-编译-c-代码" tabindex="-1"><a class="header-anchor" href="#_3-用-g-gcc-编译-c-代码" aria-hidden="true">#</a> 3. 用 <code>g++</code>/<code>gcc</code> 编译 C++ 代码</h3><p>NTL 是 <strong>C++</strong> 库，必须用 <code>g++</code>/<code>c++</code>（或 <code>clang++</code>）编译 <code>.cpp</code>，不能用 <code>gcc</code>/<code>cc</code> 直接编译，否则会报 <code>undefined reference</code> 链接错误。头文件用 <code>&lt;NTL/ZZ.h&gt;</code> 而不是 <code>&lt;ZZ.h&gt;</code>。</p><h3 id="_4-忘初始化模数就使用-zz-p" tabindex="-1"><a class="header-anchor" href="#_4-忘初始化模数就使用-zz-p" aria-hidden="true">#</a> 4. 忘初始化模数就使用 <code>ZZ_p</code></h3><p>使用 <code>ZZ_p</code> 之前必须先调用 <code>ZZ_p::init(p)</code> 设定模数 p，否则得到的是模 0 的未定义行为。模数 p 必须为素数，且应大于要参与的运算数。</p><h3 id="_5-浮点-double-与-zz-的转换陷阱" tabindex="-1"><a class="header-anchor" href="#_5-浮点-double-与-zz-的转换陷阱" aria-hidden="true">#</a> 5. 浮点 <code>double</code> 与 <code>ZZ</code> 的转换陷阱</h3><p><code>conv&lt;ZZ&gt;(3.7)</code> 这类浮点到 ZZ 的转换行为取决于舍入，可能产生非预期结果。对大数一律从字符串或整数构造：<code>conv&lt;ZZ&gt;(&quot;...&quot;)</code>、<code>conv&lt;ZZ&gt;(123)</code>，避免经浮点中转。</p><h3 id="_6-性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#_6-性能与安全注意点" aria-hidden="true">#</a> 6. 性能与安全注意点</h3><ul><li>NTL 是<strong>研究/教学友好</strong>的库，但底层算法（如默认大整数、素性判定、随机数）若不针对安全强化，<strong>不建议直接用于生产级密码学密钥生成</strong>；<code>ProbPrime</code> 只是概率素性判定，轮数 t 越大误判概率越低（约为 <code>4^(-t)</code>）；对密码学应用还需结合确定性验证（如 BPSW 或通用素数证明）。</li><li>LLL 约化的 <code>delta</code> 越大越接近严格 LLL，但时间和内存开销随之上升，按需权衡。</li><li>Homebrew 的 <code>ntl</code> 默认以发布优化构建（含 GMP），性能已较优；如需自研构建，务必开启优化 <code>-O2</code> 并启用 GMP。</li></ul><h3 id="_7-随机数安全-random-zz-p-与密码学随机" tabindex="-1"><a class="header-anchor" href="#_7-随机数安全-random-zz-p-与密码学随机" aria-hidden="true">#</a> 7. 随机数安全：<code>random_ZZ_p()</code> 与密码学随机</h3><p>NTL 内置随机数生成器<strong>不适合直接用作密码学安全随机源</strong>。密钥、盐、nonce 等应由系统 CSPRNG 生成（如 <code>/dev/urandom</code>、<code>/dev/random</code> 或 <code>getrandom()</code>），再经 <code>conv&lt;ZZ&gt;(...)</code> 喂入 NTL。固定种子的 <code>SetSeed</code> 仅用于可复现的科研/调试，绝不用于生产密钥。</p><h3 id="_8-新手常见踩坑汇总" tabindex="-1"><a class="header-anchor" href="#_8-新手常见踩坑汇总" aria-hidden="true">#</a> 8. 新手常见踩坑汇总</h3><table><thead><tr><th>现象</th><th>常见原因</th><th>解决办法</th></tr></thead><tbody><tr><td>编译报 <code>error: no member named &#39;inv&#39; in namespace &#39;NTL&#39;</code></td><td>忘了 <code>#include &lt;NTL/ZZ_p.h&gt;</code></td><td>引入对应头文件</td></tr><tr><td>链接报 <code>_ZN3NTL... undefined</code></td><td>编译用了 <code>gcc</code> 而非 <code>g++</code></td><td>改用 <code>c++</code>/<code>clang++</code></td></tr><tr><td>运行报 <code>arithmetic error</code> 或异常</td><td><code>ZZ_p</code> 用了合数模、或对 0 求逆</td><td>用素数模，求逆前判 <code>x != 0</code></td></tr><tr><td>结果与预期不一致、全为 0</td><td>忘了调用 <code>ZZ_p::init(p)</code></td><td>使用 <code>ZZ_p</code> 前先初始化模数</td></tr><tr><td><code>pkg-config</code> 找不到 ntl</td><td><code>PKG_CONFIG_PATH</code> 未包含 brew 的 pkgconfig</td><td>显式 <code>export PKG_CONFIG_PATH=...</code></td></tr><tr><td>编译极慢或内存大</td><td>未开优化或 debug 构建</td><td>加 <code>-O2</code></td></tr></tbody></table><h3 id="_9-大整数类型混合与-conv-zz-的注意点" tabindex="-1"><a class="header-anchor" href="#_9-大整数类型混合与-conv-zz-的注意点" aria-hidden="true">#</a> 9. 大整数类型混合与 <code>conv&lt;ZZ&gt;</code> 的注意点</h3><p><code>ZZ</code>、<code>long</code>、<code>string</code> 之间转换都用 <code>conv&lt;T&gt;(...)</code>：<code>conv&lt;ZZ&gt;(12345L)</code>、<code>conv&lt;ZZ&gt;(string)</code>。注意 <code>long</code> 是 64 位，超过其范围的值必须从字符串构造；混用不同类型做运算前先统一为 <code>ZZ</code>，避免隐式截断。</p><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-openssl-libcrypto-搭配做-实验级-密码学验证" tabindex="-1"><a class="header-anchor" href="#_1-与-openssl-libcrypto-搭配做-实验级-密码学验证" aria-hidden="true">#</a> 1. 与 OpenSSL/libcrypto 搭配做&quot;实验级&quot;密码学验证</h3><p>NTL 常用于教学与论文复现，而 OpenSSL 提供生产级哈希与随机源。可组合：用 <code>/dev/urandom</code> 生成随机字节 → <code>conv&lt;ZZ&gt;</code> 转大整数 → NTL 做素性/模幂验证。参考脚本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 生成 256 位随机整数（非密码学用途演示）</span>
<span class="token function">head</span> <span class="token parameter variable">-c</span> <span class="token number">32</span> /dev/urandom <span class="token operator">|</span> od <span class="token parameter variable">-An</span> <span class="token parameter variable">-tu8</span> <span class="token operator">|</span> <span class="token function">tr</span> <span class="token parameter variable">-d</span> <span class="token string">&#39; &#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print}&#39;</span> <span class="token operator">&gt;</span> rnd.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>C++ 端用 <code>GetRandomBytes</code>（NTL 提供）或系统调用读取随机源：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ_p.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token keyword">using</span> <span class="token keyword">namespace</span> NTL<span class="token punctuation">;</span>

ZZ <span class="token function">random_from_urandom</span><span class="token punctuation">(</span><span class="token keyword">int</span> bytes<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">unsigned</span> <span class="token keyword">char</span> buf<span class="token punctuation">[</span><span class="token number">64</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    FILE <span class="token operator">*</span>f <span class="token operator">=</span> <span class="token function">fopen</span><span class="token punctuation">(</span><span class="token string">&quot;/dev/urandom&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;rb&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>f<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">to_ZZ</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    size_t got <span class="token operator">=</span> <span class="token function">fread</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> bytes<span class="token punctuation">,</span> f<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">fclose</span><span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// 转成十六进制字符串再转 ZZ</span>
    std<span class="token double-colon punctuation">::</span>string hex<span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span>size_t i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> got<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">char</span> tmp<span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token function">snprintf</span><span class="token punctuation">(</span>tmp<span class="token punctuation">,</span> <span class="token keyword">sizeof</span> tmp<span class="token punctuation">,</span> <span class="token string">&quot;%02x&quot;</span><span class="token punctuation">,</span> buf<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        hex <span class="token operator">+=</span> tmp<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token string">&quot;0x&quot;</span> <span class="token operator">+</span> hex<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：上面 <code>conv&lt;ZZ&gt;(&quot;0x...&quot;)</code> 接受十六进制前缀字符串；NTL 的 <code>conv&lt;ZZ&gt;</code> 支持 <code>0x</code>/<code>0X</code> 前缀解析。生产级密码学请直接依赖 OpenSSL 的 <code>RAND_bytes</code>，此处仅为教学演示。</p></blockquote><h3 id="_2-makefile-自动化编译" tabindex="-1"><a class="header-anchor" href="#_2-makefile-自动化编译" aria-hidden="true">#</a> 2. Makefile 自动化编译</h3><p>写一个可复用的 <code>Makefile</code>，让 <code>make</code> 自动处理编译、链接、清理：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile —— NTL 示例</span>
CXX      <span class="token operator">?=</span> c++
CXXFLAGS <span class="token operator">?=</span> -std<span class="token operator">=</span>c++17 -O2
CPPFLAGS <span class="token operator">+=</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">shell</span> pkg-config --cflags ntl<span class="token punctuation">)</span>
LDLIBS   <span class="token operator">+=</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">shell</span> pkg-config --libs ntl<span class="token punctuation">)</span>

TARGETS <span class="token operator">:=</span> ntl_demo zzp_demo poly_demo

<span class="token target symbol">all</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>TARGETS<span class="token punctuation">)</span>

<span class="token target symbol">%</span><span class="token punctuation">:</span> %.cpp
	<span class="token variable">$</span><span class="token punctuation">(</span>CXX<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>CXXFLAGS<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>CPPFLAGS<span class="token punctuation">)</span> <span class="token variable">$&lt;</span> -o <span class="token variable">$@</span> <span class="token variable">$</span><span class="token punctuation">(</span>LDLIBS<span class="token punctuation">)</span>

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -f <span class="token variable">$</span><span class="token punctuation">(</span>TARGETS<span class="token punctuation">)</span> *.o

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> all clean
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">make</span>            <span class="token comment"># 编译所有目标</span>
<span class="token function">make</span> ntl_demo   <span class="token comment"># 只编译 ntl_demo</span>
<span class="token function">make</span> clean
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-ci-集成-github-actions" tabindex="-1"><a class="header-anchor" href="#_3-ci-集成-github-actions" aria-hidden="true">#</a> 3. CI 集成（GitHub Actions）</h3><p>在仓库中放一个 <code>.github/workflows/ntl.yml</code> 实现&quot;安装依赖 → 构建 → 跑测试&quot;的 CI：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> ntl<span class="token punctuation">-</span>build
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">,</span> pull_request<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install deps
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          sudo apt-get update
          sudo apt-get install -y libntl-dev libgmp-dev pkg-config</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build
        <span class="token key atrule">run</span><span class="token punctuation">:</span> make all
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Run tests
        <span class="token key atrule">run</span><span class="token punctuation">:</span> ./ntl_demo <span class="token important">&amp;&amp;</span> ./zzp_demo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在 macOS runner 上则用 Homebrew：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code>      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install (macOS)
        <span class="token key atrule">if</span><span class="token punctuation">:</span> runner.os == &#39;macOS&#39;
        <span class="token key atrule">run</span><span class="token punctuation">:</span> brew install ntl
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-批量处理-遍历多个模数-参数" tabindex="-1"><a class="header-anchor" href="#_4-批量处理-遍历多个模数-参数" aria-hidden="true">#</a> 4. 批量处理：遍历多个模数/参数</h3><p>科研中常需对不同参数批量运行同一算法。用 shell 循环 + 命令行参数即可：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// batch.cpp —— 从 argv 读入模数 p 与指数 e</span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;NTL/ZZ_p.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token keyword">using</span> <span class="token keyword">namespace</span> NTL<span class="token punctuation">;</span> <span class="token keyword">using</span> <span class="token keyword">namespace</span> std<span class="token punctuation">;</span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token keyword">int</span> argc<span class="token punctuation">,</span> <span class="token keyword">char</span> <span class="token operator">*</span><span class="token operator">*</span>argv<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>argc <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> cerr <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;usage: batch &lt;p&gt; &lt;e&gt;\\n&quot;</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    ZZ p <span class="token operator">=</span> <span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>argv<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">long</span> e <span class="token operator">=</span> <span class="token function">atol</span><span class="token punctuation">(</span>argv<span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">ZZ_p</span><span class="token double-colon punctuation">::</span><span class="token function">init</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span><span class="token punctuation">;</span>
    ZZ_p a <span class="token operator">=</span> <span class="token generic-function"><span class="token function">conv</span><span class="token generic class-name"><span class="token operator">&lt;</span>ZZ_p<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// a = 2</span>
    ZZ_p r <span class="token operator">=</span> <span class="token function">power</span><span class="token punctuation">(</span>a<span class="token punctuation">,</span> e<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 2^e mod p</span>
    cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;2^&quot;</span> <span class="token operator">&lt;&lt;</span> e <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; mod &quot;</span> <span class="token operator">&lt;&lt;</span> p <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; = &quot;</span> <span class="token operator">&lt;&lt;</span> r <span class="token operator">&lt;&lt;</span> endl<span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 bash 循环批量执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>c++ batch.cpp <span class="token parameter variable">-o</span> batch <span class="token variable"><span class="token variable">$(</span>pkg-config <span class="token parameter variable">--cflags</span> <span class="token parameter variable">--libs</span> ntl<span class="token variable">)</span></span>

<span class="token comment"># 对一组素数分别计算 2^123456 mod p</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">p</span> <span class="token keyword">in</span> <span class="token number">1000000007</span> <span class="token number">1000000009</span> <span class="token number">1000000021</span> <span class="token number">1000000033</span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">echo</span> <span class="token string">&quot;== p=<span class="token variable">$p</span> ==&quot;</span>
  ./batch <span class="token variable">$p</span> <span class="token number">123456</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-与其它工具管道组合" tabindex="-1"><a class="header-anchor" href="#_5-与其它工具管道组合" aria-hidden="true">#</a> 5. 与其它工具管道组合</h3><p>NTL 本身是库，但可与命令行工具组合成&quot;文本管道&quot;。例如把生成的随机素数写入文件供后续脚本消费：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># gen_prime.cpp 输出一个随机 n 位素数到 stdout</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> gen_prime.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;NTL/ZZ.h&gt;
#include &lt;iostream&gt;
using namespace NTL; using namespace std;
int main(int argc, char **argv) {
    long bits = (argc &gt; 1) ? atol(argv[1]) : 256;
    cout &lt;&lt; RandomPrime_ZZ(bits) &lt;&lt; endl;
    return 0;
}
EOF</span>
c++ gen_prime.cpp <span class="token parameter variable">-o</span> gen_prime <span class="token variable"><span class="token variable">$(</span>pkg-config <span class="token parameter variable">--cflags</span> <span class="token parameter variable">--libs</span> ntl<span class="token variable">)</span></span>

<span class="token comment"># 生成 10 个 256 位素数，写入 primes.txt</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">i</span> <span class="token keyword">in</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">seq</span> <span class="token number">1</span> <span class="token number">10</span><span class="token variable">)</span></span><span class="token punctuation">;</span> <span class="token keyword">do</span> ./gen_prime <span class="token number">256</span><span class="token punctuation">;</span> <span class="token keyword">done</span> <span class="token operator">&gt;</span> primes.txt
<span class="token function">wc</span> <span class="token parameter variable">-l</span> primes.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-生产级实践要点" tabindex="-1"><a class="header-anchor" href="#_6-生产级实践要点" aria-hidden="true">#</a> 6. 生产级实践要点</h3><ul><li><strong>密钥与秘密值</strong>：永远用系统 CSPRNG 生成，不用固定种子。</li><li><strong>素性验证</strong>：<code>ProbPrime</code> 后对关键场景再做确定性证明，或直接使用经过验证的 <code>PrimeGen</code>（NTL 的确定性素数生成，可用于 RSA 密钥生成）。</li><li><strong>构建策略</strong>：生产环境编译用 <code>-O2</code> 并启用 GMP；把 <code>pkg-config</code> 参数固化进构建系统（CMake/Make/Bazel），避免手写路径漂移。</li><li><strong>内存与时间</strong>：大位宽（≥4096 位）模幂耗时明显，可先用更小位宽验证逻辑正确性，再放大到生产位宽。</li><li><strong>可复现</strong>：科研论文复现实验务必先 <code>SetSeed(固定值)</code> 并记录种子。</li><li><strong>Bazel/CMake 集成</strong>：CMake 用 <code>pkg_check_modules</code>；Bazel 可用 <code>cc_library</code> + <code>linkopts = [&quot;$(pkg-config --libs ntl)&quot;]</code> 或直接写 <code>-L/opt/homebrew/lib -lntl</code>。</li></ul><hr><blockquote><p>提示：以上代码均为真实可编译的 NTL 用法；编译前请确认 <code>pkg-config --modversion ntl</code> 能正常输出版本号。本文档聚焦 Homebrew 安装的 NTL 11.x，若手动源码构建，注意 <code>./configure</code> 选项（<code>NTL_GMP_LIP=on</code>、<code>NTL_THREADS</code> 等）与 brew 默认配置可能不同。</p></blockquote>`,99),c=[o];function p(l,i){return s(),a("div",null,c)}const u=n(t,[["render",p],["__file","ntl.html.vue"]]);export{u as default};
